INSERT INTO salary_formula (key, expression, label) VALUES ('baseSalary', 'employee.baseSalary', 'Lương cơ bản');
INSERT INTO salary_formula (key, expression, label) VALUES ('allowance', 'employee.allowance', 'Phụ cấp');
INSERT INTO salary_formula (key, expression, label) VALUES ('overtimeAmount', 'overtimeHours * hourlyRate * 1.5', 'Tiền tăng ca');
INSERT INTO salary_formula (key, expression, label) VALUES ('grossSalary', 'baseSalary + allowance + overtimeAmount', 'Tổng thu nhập');
INSERT INTO salary_formula (key, expression, label) VALUES ('insuranceDeduction', 'insSalaryBase * (bhxhEmployeeRate + bhytEmployeeRate + bhtnEmployeeRate)', 'Khấu trừ bảo hiểm');
INSERT INTO salary_formula (key, expression, label) VALUES ('taxableIncome', 'grossSalary - insuranceDeduction - personalDeduction - dependents * dependentDeduction', 'Thu nhập chịu thuế');
INSERT INTO salary_formula (key, expression, label) VALUES ('personalIncomeTax', 'progressiveTax(taxableIncome)', 'Thuế TNCN');
INSERT INTO salary_formula (key, expression, label) VALUES ('netSalary', 'grossSalary - insuranceDeduction - personalIncomeTax', 'Lương thực nhận');
